export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter(([x, y]) => {
    const neighbourCount = liveCells.filter(
      ([otherX, otherY]) =>
        !(otherX === x && otherY === y) &&
        Math.abs(otherX - x) <= 1 &&
        Math.abs(otherY - y) <= 1,
    ).length;

    return neighbourCount === 3;
  });
}

